<section class="analytics-kpi-strip descriptive-six-kpis"><x-analytics.kpi label="Distance Traveled" :value="number_format($fleet['totalDistance']??0,1).' km'" small="Total distance" icon="fa-location-dot"/><x-analytics.kpi label="Average Speed" :value="number_format($fleet['averageSpeed']??0,1).' km/h'" small="Average while in motion" icon="fa-gauge-high" tone="green"/><x-analytics.kpi label="Idle Time" :value="number_format(($fleet['totalIdleMinutes']??0)/60,1).' hrs'" small="Recorded idle time" icon="fa-hourglass-half" tone="yellow"/><x-analytics.kpi label="Avg. Trip Duration" :value="number_format($fleet['averageTripDuration']??0,1).' min'" small="Average per trip" icon="fa-clock" tone="purple"/><x-analytics.kpi label="Trips Processed" :value="number_format($fleet['tripCount']??0)" small="Processed GPS trips" icon="fa-route"/><x-analytics.kpi label="Buses Active" :value="number_format($fleet['activeBuses']??0)" small="Current active buses" icon="fa-bus" tone="green"/></section>